const https = require("https");
const fs = require("fs");
const { spawnSync } = require("child_process");
const version = "{{MC_VERSION}}";
const requestedLoader = "{{LOADER_VERSION}}";
const installerVersion = "{{INSTALLER_VERSION}}";

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { "user-agent": "terrypanel" } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        return get(res.headers.location).then(resolve, reject);
      }
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    }).on("error", reject);
  });
}

(async () => {
  let loader = requestedLoader;
  if (!loader || loader === "latest") {
    const meta = JSON.parse((await get(`https://meta.fabricmc.net/v2/versions/loader/${version}`)).body.toString("utf8"));
    loader = meta[0].loader.version;
  }
  const installerUrl = `https://maven.fabricmc.net/net/fabricmc/fabric-installer/${installerVersion}/fabric-installer-${installerVersion}.jar`;
  console.log(`Downloading Fabric installer ${installerVersion}`);
  const installer = await get(installerUrl);
  if (installer.status !== 200) throw new Error(`Fabric installer download returned ${installer.status}`);
  fs.writeFileSync("fabric-installer.jar", installer.body);
  console.log(`Installing Fabric loader ${loader} for Minecraft ${version}`);
  const result = spawnSync("java", [
    "-jar", "fabric-installer.jar", "server",
    "-mcversion", version,
    "-loader", loader,
    "-downloadMinecraft",
  ], { stdio: "inherit" });
  if (result.status !== 0) throw new Error(`Fabric installer exited with code ${result.status}`);
  console.log("Fabric server installed. Start it with start.sh or the panel Start button.");
})().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
